// Subscribe once, for example in the form constructor
pnlContent.Paint += PnlContent_Paint;

private void PnlContent_Paint(object sender, PaintEventArgs e)
{
    e.Graphics.DrawRectangle(Pens.SteelBlue, 0, 0, pnlContent.Width - 1, pnlContent.Height - 1);
}

// Subscribe once, for example in the form constructor
pnlContent.Resize += PnlContent_Resize;

private void PnlContent_Resize(object sender, EventArgs e)
{
    this.Text = "Panel size: " + pnlContent.Size;
}

// Subscribe once, for example in the form constructor
pnlContent.ControlAdded += PnlContent_ControlAdded;

private void PnlContent_ControlAdded(object sender, ControlEventArgs e)
{
    this.Text = "Added: " + e.Control.Name;
}

// Subscribe once, for example in the form constructor
grpOptions.Enter += GrpOptions_Enter;

private void GrpOptions_Enter(object sender, EventArgs e)
{
    grpOptions.Text = "Options (active)";
}

// Subscribe once, for example in the form constructor
grpOptions.Paint += GrpOptions_Paint;

private void GrpOptions_Paint(object sender, PaintEventArgs e)
{
    e.Graphics.DrawLine(Pens.SteelBlue, 0, grpOptions.Height - 1, grpOptions.Width, grpOptions.Height - 1);
}

// Subscribe once, for example in the form constructor
tabMain.SelectedIndexChanged += TabMain_SelectedIndexChanged;

private void TabMain_SelectedIndexChanged(object sender, EventArgs e)
{
    this.Text = "Tab: " + tabMain.SelectedTab.Text;
}

// Subscribe once, for example in the form constructor
tabMain.Selecting += TabMain_Selecting;

private void TabMain_Selecting(object sender, TabControlCancelEventArgs e)
{
    if (e.TabPage.Text == "Admin")
    {
        e.Cancel = true;
        MessageBox.Show("The Admin tab is locked.");
    }
}

// Subscribe once, for example in the form constructor
tabMain.Selected += TabMain_Selected;

private void TabMain_Selected(object sender, TabControlEventArgs e)
{
    this.Text = "Now showing " + e.TabPage.Text;
}

// Subscribe once, for example in the form constructor
tabMain.Deselecting += TabMain_Deselecting;

private void TabMain_Deselecting(object sender, TabControlCancelEventArgs e)
{
    DialogResult answer = MessageBox.Show("Leave this tab?", "Confirm", MessageBoxButtons.YesNo);
    e.Cancel = answer == DialogResult.No;
}

// Subscribe once, for example in the form constructor
tabGeneral.Enter += TabGeneral_Enter;

private void TabGeneral_Enter(object sender, EventArgs e)
{
    this.Text = "Entered " + tabGeneral.Text;
}

// Subscribe once, for example in the form constructor
tabGeneral.Leave += TabGeneral_Leave;

private void TabGeneral_Leave(object sender, EventArgs e)
{
    this.Text = "Left " + tabGeneral.Text;
}

// Subscribe once, for example in the form constructor
split.SplitterMoved += Split_SplitterMoved;

private void Split_SplitterMoved(object sender, SplitterEventArgs e)
{
    this.Text = "Splitter at " + e.SplitX;
}

// Subscribe once, for example in the form constructor
split.SplitterMoving += Split_SplitterMoving;

private void Split_SplitterMoving(object sender, SplitterCancelEventArgs e)
{
    if (e.SplitX < 100)
    {
        e.Cancel = true;
    }
}

// Subscribe once, for example in the form constructor
flow.ControlAdded += Flow_ControlAdded;

private void Flow_ControlAdded(object sender, ControlEventArgs e)
{
    this.Text = "Controls: " + flow.Controls.Count;
}

// Subscribe once, for example in the form constructor
flow.ControlRemoved += Flow_ControlRemoved;

private void Flow_ControlRemoved(object sender, ControlEventArgs e)
{
    this.Text = "Removed: " + e.Control.Name;
}

// Subscribe once, for example in the form constructor
tlp.CellPaint += Tlp_CellPaint;

private void Tlp_CellPaint(object sender, TableLayoutCellPaintEventArgs e)
{
    if (e.Row == 0)
    {
        e.Graphics.FillRectangle(Brushes.LightSteelBlue, e.CellBounds);
    }
}
